-- sync_info policy; anon cannot read sync_info.
REVOKE ALL ON FUNCTION public.generic_entity_access FROM anon;


ALTER TABLE public.sync_info ENABLE ROW LEVEL SECURITY;
== assets
        AND (space_id, source_local_id) IN (SELECT space_id, source_local_id FROM public.my_accessible_resources())
    );

-- Single-table views are writable, and writes run as the view owner, bypassing FileReference's RLS.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.my_file_references FROM anon, authenticated;

GRANT ALL ON TABLE public."FileReference" TO authenticated;
GRANT ALL ON TABLE public."FileReference" TO service_role;
REVOKE ALL ON TABLE public."FileReference" FROM anon;

ALTER TABLE public.file_gc OWNER TO "postgres";

GRANT ALL ON TABLE public.file_gc TO service_role;
REVOKE ALL ON TABLE public.file_gc FROM authenticated;
REVOKE ALL ON TABLE public.file_gc FROM anon;

-- we could also find out if the storage exists, but not sure how that works with ACLs.
-- This is both faster and safer.
CREATE OR REPLACE FUNCTION public.file_exists(hashvalue VARCHAR) RETURNS boolean
SET search_path = ''
SECURITY DEFINER
LANGUAGE sql AS $$
SELECT EXISTS (SELECT true FROM public."FileReference" WHERE filehash = hashvalue LIMIT 1);
$$;

-- uploadFile and Roam asset sharing call it after logging in.
REVOKE ALL ON FUNCTION public.file_exists FROM anon;

CREATE OR REPLACE FUNCTION public.file_access(hashvalue VARCHAR) RETURNS boolean
== secret
    INSERT INTO public.secret_token (payload, expiry_date, one_time_use) VALUES (v_payload, now()+expiry_interval, v_one_time_use) RETURNING id;
$$;

-- Admin panels and the website call it after logging in; creator defaults to auth.uid(), which is NOT NULL.
REVOKE ALL ON FUNCTION public.create_secret_token FROM anon;

CREATE OR REPLACE FUNCTION public.get_secret_token(token VARCHAR) RETURNS JSONB
SECURITY DEFINER
SET search_path = ''
LANGUAGE plpgsql AS $$
DECLARE
v_payload JSONB;
v_one_time_use BOOLEAN;
BEGIN
    DELETE FROM public.secret_token WHERE expiry_date < now();
    DELETE FROM public.secret_token WHERE id=token AND one_time_use = true RETURNING payload INTO v_payload;
    IF v_payload IS NULL THEN
        SELECT payload INTO v_payload FROM public.secret_token WHERE id=token;
    END IF;
    RETURN v_payload;
END;
$$;

-- The website's /auth/token route hands a plugin's session to a browser that isn't logged in yet.
GRANT EXECUTE ON FUNCTION public.get_secret_token TO anon;

ALTER TABLE public.secret_token OWNER TO "postgres";

REVOKE ALL ON TABLE public.secret_token FROM anon;
GRANT ALL ON TABLE public.secret_token TO authenticated;
GRANT ALL ON TABLE public.secret_token TO service_role;

